from typing import Final

BITS: Final[int] = 8
MASK: Final[int] = 0xFF


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits (0 <= k <= 7), wrapping high bits to low.

    x must be in 0..255 and k in 0..7. The result is in 0..255.
    """
    return ((x << k) | (x >> (BITS - k))) & MASK


def test_rotl8_zero_shift_is_identity() -> None:
    assert rotl8(0x5A, 0) == 0x5A
    assert rotl8(0, 0) == 0
    assert rotl8(255, 0) == 255


def test_rotl8_single_bit() -> None:
    assert rotl8(0b0000_0001, 1) == 0b0000_0010
    assert rotl8(0b0000_0001, 7) == 0b1000_0000


def test_rotl8_wraps_high_bit() -> None:
    assert rotl8(0b1000_0000, 1) == 0b0000_0001
    assert rotl8(0b1000_0001, 1) == 0b0000_0011


def test_rotl8_nibble_swap() -> None:
    assert rotl8(0x12, 4) == 0x21


def test_rotl8_all_ones_is_fixed() -> None:
    for k in range(BITS):
        assert rotl8(255, k) == 255


def test_rotl8_result_in_range() -> None:
    for x in range(MASK + 1):
        for k in range(BITS):
            assert 0 <= rotl8(x, k) <= MASK
